public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.round(n * 0.05);
    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);
    double sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (n - 2 * k);
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] sum = new int[n / 2];
    for (int i = 0; i < n / 2; i++) {
        sum[i] = arr[i] + arr[n - i - 1];
    }
    for (int i = 0; i < n / 2; i++) {
        if (sum[i] % k != 0) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with n nodes and edges
    Graph graph = new Graph(n, edges);

    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a priority queue to store the nodes to visit
    PriorityQueue<Node> queue = new PriorityQueue<>();

    // Add the root node to the queue
    queue.add(new Node(0, 0));

    // Initialize the minimum time required to collect all the apples and return to node 0
    int minTime = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the node with the minimum distance from the queue
        Node node = queue.poll();

        // If the node has not been visited before, mark it as visited and add its neighbors to the queue
        if (!visited[node.id]) {
            visited[node.id] = true;
            for (int neighbor : graph.getNeighbors(node.id)) {
                if (!visited[neighbor]) {
                    queue.add(new Node(neighbor, node.distance + 1));
                }
            }
        }

        // If the node has an apple, update the minimum time required to collect all the apples and return to node 0
        if (hasApple[node.id]) {
            minTime = Math.max(minTime, node.distance);
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTime;
}

