public static int[] diagonalOrder(int[][] mat) {
    int n = mat.length;
    int m = mat[0].length;
    int[] result = new int[n * m];
    int row = 0;
    int col = 0;
    int index = 0;
    while (row < n && col < m) {
        result[index++] = mat[row][col];
        if ((row + col) % 2 == 0) {
            if (col == m - 1) {
                row++;
            } else {
                col++;
            }
        } else {
            if (row == n - 1) {
                col++;
            } else {
                row++;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    int[] digits = new int[10];
    int digitCount = 0;
    while (n > 0) {
        digits[digitCount++] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits, 0, digitCount);
    int smallestInteger = 0;
    for (int i = digitCount - 1; i >= 0; i--) {
        smallestInteger = smallestInteger * 10 + digits[i];
    }
    return smallestInteger;
}

