public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int factor2 = 2, factor3 = 3, factor5 = 5;
    for (int i = 1; i < n; i++) {
        int min = Math.min(factor2, Math.min(factor3, factor5));
        uglyNumbers[i] = min;
        if (min == factor2) {
            i2++;
            factor2 = uglyNumbers[i2] * 2;
        }
        if (min == factor3) {
            i3++;
            factor3 = uglyNumbers[i3] * 3;
        }
        if (min == factor5) {
            i5++;
            factor5 = uglyNumbers[i5] * 5;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            if (currentLength > energy) {
                energy = currentLength;
            }
            currentChar = s.charAt(i);
            currentLength = 1;
        }
    }
    if (currentLength > energy) {
        energy = currentLength;
    }
    return energy;
}

